#!/usr/bin/env python3
import json,re
from pathlib import Path
from html import escape
ROOT=Path(__file__).resolve().parents[1]
DATE='2026-09-08'; BASE='https://epochlex.justathoughtblog.org'
BATCH=[
{'term':'Latent Space','slug':'latent-space','pronunciation':'LAY-tent spays','definition':'A learned representation space in which an AI or machine-learning model encodes features or concepts as numerical positions or directions, so items with related learned characteristics may be represented near one another.','example':'The model mapped visually similar images to nearby regions of its latent space.','categories':['AI Systems & Technical Concepts'],'aliases':['Latent representation space'],'status':'Established technical term','partOfSpeech':'noun','related':['embedding','vector-search','neural-network'],'sources':[{'id':'google-ml-latent-space-2026','type':'reference','publisher':'Google for Developers','title':'Machine Learning Glossary','published':'2026','url':'https://developers.google.com/machine-learning/glossary','supports':['definition','usage']}]},
{'term':'AI Assurance','slug':'ai-assurance','pronunciation':'A-I uh-SHOOR-uns','definition':'The practice of gathering and evaluating evidence that an AI system performs as intended within defined conditions and that relevant risks, trustworthiness properties, and safeguards have been assessed.','example':'The organization used AI assurance activities to document evidence about model performance, safety, and controls before deployment.','categories':['AI Risks, Safety & Governance','AI Ways of Working'],'aliases':['Artificial intelligence assurance'],'status':'Established governance and assurance term','partOfSpeech':'noun','related':['responsible-ai','ai-governance','eval','red-teaming'],'sources':[{'id':'nist-ai-assurance-2022','type':'primary','publisher':'NIST','title':'The Path to Consensus on Artificial Intelligence Assurance','published':'2022-03-15','url':'https://www.nist.gov/publications/path-consensus-artificial-intelligence-assurance','supports':['definition','usage']}]},
{'term':'Subagent','slug':'subagent','pronunciation':'sub-AY-jent','definition':'A specialized AI agent or agent-like worker delegated a narrower task by a primary agent or orchestration process, often with its own context, instructions, tools, or permissions.','example':'The coding agent delegated repository exploration to a subagent and used the returned summary in the main task.','categories':['AI Systems & Technical Concepts','AI Ways of Working'],'aliases':['Sub-agent'],'status':'Established emerging technical term','partOfSpeech':'noun','related':['ai-agent','agentic-workflow','orchestration','tool-calling'],'sources':[{'id':'anthropic-subagents-2026','type':'primary','publisher':'Anthropic','title':'Create custom subagents - Claude Code Docs','published':'2026','url':'https://code.claude.com/docs/en/subagents','supports':['definition','usage']}]},
{'term':'Autonomous Agent','slug':'autonomous-agent','pronunciation':'aw-TAH-nuh-mus AY-jent','definition':'An AI agent designed to pursue tasks or goals with a comparatively high degree of independent decision-making and action, requiring less step-by-step human direction than an assistant or tightly scripted workflow.','example':'The autonomous agent monitored the task, selected tools, and continued working without asking for approval after every step.','categories':['AI Systems & Technical Concepts','AI Ways of Working','AI Risks, Safety & Governance'],'aliases':['Autonomous AI agent'],'status':'Established emerging term','partOfSpeech':'noun','related':['ai-agent','agentic','agent-loop','computer-use'],'sources':[{'id':'microsoft-autonomous-agent-2026','type':'primary','publisher':'Microsoft','title':'AI Agent FAQ: Definitions and Explanations','published':'2026','url':'https://www.microsoft.com/en-us/microsoft-365-copilot/agents/ai-agents-faq','supports':['definition','usage']}]},
{'term':'AI Fluency','slug':'ai-fluency','pronunciation':'A-I FLOO-un-see','definition':'The practical ability to work with AI effectively, critically, responsibly, and safely, including knowing what to delegate, how to communicate with AI, how to evaluate its outputs, and when human judgment is required.','example':'The training program focused on AI fluency rather than simply teaching employees which buttons to press in a specific chatbot.','categories':['AI Ways of Working','AI Risks, Safety & Governance'],'aliases':['Artificial intelligence fluency'],'status':'Established emerging education and workplace term','partOfSpeech':'noun','related':['ai-literacy','human-ai-collaboration','responsible-ai','prompt-engineering'],'sources':[{'id':'anthropic-ai-fluency-2026','type':'primary','publisher':'Anthropic','title':'AI Fluency: The AI Fluency Framework','published':'2026','url':'https://www.anthropic.com/ai-fluency/overview','supports':['definition','usage']}]}
]

def page(t):
 term=escape(t['term']); d=escape(t['definition'],quote=True); p=escape(t['pronunciation']); slug=t['slug']; url=f'{BASE}/terms/{slug}/'; ld=json.dumps({'@context':'https://schema.org','@type':'DefinedTerm','name':t['term'],'description':t['definition'],'url':url,'inDefinedTermSet':BASE+'/','inLanguage':'en'},ensure_ascii=False)
 return f'''<!doctype html>\n<html lang="en">\n<head>\n  <meta charset="utf-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1">\n  <meta name="color-scheme" content="light dark">\n  <title>{term} | EpochLex</title>\n  <meta name="description" content="{d}">\n  <link rel="canonical" href="{url}">\n  <meta property="og:site_name" content="EpochLex">\n  <meta property="og:title" content="{term} | EpochLex">\n  <meta property="og:description" content="{d}">\n  <meta property="og:type" content="article">\n  <meta property="og:url" content="{url}">\n  <meta name="twitter:card" content="summary">\n  <meta name="twitter:title" content="{term} | EpochLex">\n  <meta name="twitter:description" content="{d}">\n  <script type="application/ld+json">{ld}</script>\n  <script>(()=>{{try{{const saved=localStorage.getItem("ai-era-theme");const systemDark=window.matchMedia("(prefers-color-scheme: dark)").matches;document.documentElement.dataset.theme=saved||(systemDark?"dark":"light");}}catch(_){{document.documentElement.dataset.theme="light";}}}})();</script>\n  <link rel="stylesheet" href="../../assets/css/styles.css">\n  <link rel="stylesheet" href="../../assets/css/term-pages.css">\n  <link rel="stylesheet" href="../../assets/css/brand-theme.css">\n</head>\n<body>\n<header class="site-header"><div class="shell header-inner"><a class="brand" href="../../" aria-label="EpochLex home"><span class="brand-lockup" aria-hidden="true"><img class="brand-lockup-image brand-lockup-light" src="../../assets/brand/epochlex/epochlex-logo-horizontal-light.png" alt=""><img class="brand-lockup-image brand-lockup-dark" src="../../assets/brand/epochlex/epochlex-logo-horizontal-dark.png" alt=""></span><span class="sr-only">EpochLex</span></a><nav class="primary-nav" aria-label="Primary navigation"><a class="active" href="../../">Browse</a><a href="../../categories.html">Categories</a><a href="../../about.html">About</a><a href="../../contribute.html">Contribute</a><a href="../../methodology.html">Methodology</a></nav><button id="theme-toggle" class="theme-toggle" type="button" aria-label="Switch color theme" title="Switch color theme"><span class="sun" aria-hidden="true">☼</span><span class="toggle-track"><span class="toggle-knob"></span></span><span class="moon" aria-hidden="true">☾</span></button></div></header>\n<main id="term-page" class="term-page shell" data-term-slug="{slug}"><div id="term-fallback" class="term-fallback"><nav class="term-breadcrumb" aria-label="Breadcrumb"><a href="../../">Browse</a><span aria-hidden="true">/</span><span>{term}</span></nav><p class="eyebrow">EpochLex entry</p><h1>{term}</h1><p class="fallback-pronunciation">{p}</p><p class="fallback-definition">{escape(t['definition'])}</p></div></main>\n<footer class="site-footer"><div class="shell footer-inner"><span class="footer-mark" aria-hidden="true">◎</span><p><strong>EpochLex · Dictionary of the AI Era</strong><br>Vibe coded · Human-directed · AI-assisted · Human-reviewed</p><p class="footer-license">Code: MIT · Content: CC BY 4.0</p></div></footer><script src="../../assets/js/app.js"></script><script src="../../assets/js/term-page.js"></script>\n</body>\n</html>\n'''

terms_path=ROOT/'data/terms.json'; terms=json.loads(terms_path.read_text()); existing={x['slug'] for x in terms}
for b in BATCH:
 if b['slug'] in existing: raise SystemExit(f'already published: {b["slug"]}')
 rec={k:v for k,v in b.items() if k not in ('related','sources')}; rec.update({'added':DATE,'lastReviewed':DATE,'sources':[]}); terms.append(rec)
terms.sort(key=lambda x:x['term'].lower()); terms_path.write_text(json.dumps(terms,ensure_ascii=False,separators=(',',':'))+'\n')

prov_path=ROOT/'data/provenance.json'; prov=json.loads(prov_path.read_text())
for b in BATCH: prov[b['slug']]={'researchStatus':'pending','origin':None,'firstKnownUse':None,'history':[],'relatedTerms':b['related'],'sources':b['sources']}
prov_path.write_text(json.dumps(prov,ensure_ascii=False,indent=2)+'\n')
for b in BATCH:
 p=ROOT/'terms'/b['slug']; p.mkdir(parents=True,exist_ok=True); (p/'index.html').write_text(page(b))

cand=ROOT/'docs/CORPUS-CANDIDATES.md'; text=cand.read_text()
for b in BATCH: text=re.sub(r'^- '+re.escape(b['term'])+r'\s*$','',text,flags=re.M)
text=re.sub(r'\n{3,}','\n\n',text); start=text.index('## Repository roadmap candidates'); end=text.index('## Related documentation'); count=sum(1 for line in text[start:end].splitlines() if line.startswith('- ')); text=re.sub(r'\*\*Current unpublished inventory: \d+ candidates\.\*\*',f'**Current unpublished inventory: {count} candidates.**',text,count=1); cand.write_text(text)

audit=ROOT/'docs/CORPUS-AUDIT-2026-09.md'; a=audit.read_text(); section='\n## Publish — Batch D (published September 8, 2026)\n\n'
for b in BATCH:
 src='; '.join(f"[{s['publisher']}: {s['title']}]({s['url']})" for s in b['sources']); section+=f"### {b['term']}\n\n**Why publish:** {b['definition']}\n\n**Usage evidence:** {src}\n\n**Provenance state:** `pending` — meaning/usage evidence is recorded; origin, first-known-use, and fuller history research remain open.\n\n"
a=a.replace('## Publish — next qualified group',section+'## Publish — next qualified group')
for b in BATCH: a=re.sub(r'^- '+re.escape(b['term'])+r'\s*$','',a,flags=re.M)
a=a.replace('These candidates have strong reader value and should move next into definition drafting and meaning-evidence review under the new publication model:','The previously qualified queue has now been published through Batches A–D. No additional candidates are prequalified for publication in this audit; future Publish promotions should come from fresh evidence-based review of the Research Further inventory.')
a=a.replace('This audit has now published 28 candidates across Batches A, B, and C and added 172 new research candidates.','This audit has now published 33 candidates across Batches A, B, C, and D and added 172 new research candidates.')
audit.write_text(re.sub(r'\n{3,}','\n\n',a))

road=ROOT/'docs/ROADMAP.md'; r=road.read_text(); r=r.replace('- 150 published dictionary entries;','- 155 published dictionary entries;').replace('- 122 researched provenance records and 28 pending provenance records in the current published corpus;','- 122 researched provenance records and 33 pending provenance records in the current published corpus;'); road.write_text(r)

site=ROOT/'sitemap.xml'; sm=site.read_text(); blocks=''.join(f'  <url>\n    <loc>{BASE}/terms/{b["slug"]}/</loc>\n    <lastmod>{DATE}</lastmod>\n  </url>\n' for b in BATCH); sm=sm.replace('</urlset>',blocks+'</urlset>'); site.write_text(sm)

terms=json.loads(terms_path.read_text()); prov=json.loads(prov_path.read_text()); slugs={x['slug'] for x in terms}
assert len(terms)==155, len(terms); assert slugs==set(prov); assert sum(1 for x in prov.values() if x.get('researchStatus')=='pending')==33
for record in prov.values():
 for slug in record.get('relatedTerms',[]): assert slug in slugs, f'unpublished related term: {slug}'
for b in BATCH: assert (ROOT/'terms'/b['slug']/'index.html').exists()
assert count==718, count
print('Validated 155 published entries, 33 pending provenance records, 718 candidates, and related-term parity.')